const CACHE='devotionals-mobile-v1';
const FILES=['./','index.html','style.css','app.js','manifest.webmanifest','assets/icon-192.png','assets/icon-512.png','assets/rain.mp3'];
self.addEventListener('install',event=>event.waitUntil(caches.open(CACHE).then(c=>c.addAll(FILES))));
self.addEventListener('activate',event=>event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('devotionals-mobile-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',event=>{const request=event.request;if(request.method!=='GET'||new URL(request.url).origin!==self.location.origin)return;
event.respondWith((async()=>{const cached=await caches.match(request.url);if(cached){const range=request.headers.get('range');if(range&&new URL(request.url).pathname.endsWith('.mp3')){const bytes=await cached.arrayBuffer();const match=/^bytes=(\d+)-(\d*)$/.exec(range);if(match){const start=Number(match[1]),end=match[2]?Math.min(Number(match[2]),bytes.byteLength-1):bytes.byteLength-1;if(start>=bytes.byteLength||start>end)return new Response(null,{status:416,headers:{'Content-Range':`bytes */${bytes.byteLength}`}});return new Response(bytes.slice(start,end+1),{status:206,headers:{'Content-Type':'audio/mpeg','Content-Range':`bytes ${start}-${end}/${bytes.byteLength}`,'Content-Length':String(end-start+1),'Accept-Ranges':'bytes'}})}}return cached;}try{return await fetch(request)}catch(error){if(request.mode==='navigate')return caches.match('index.html');throw error}})());});
